def consume_stock(stock, requests):
    for item, quantity in requests:
        stock[item] -= quantity
    return stock

extraction.python:
import solution; stock = {"apples": 10, "bananas": 5}; requests = [("apples", 3), ("bananas", 2)]; try:
    solution.consume_stock(stock, requests)
    assert stock["apples"] == 7 and stock["bananas"] == 3, "Stock not updated correctly"
except Exception as e:
    print(f"Error: {e}")

